import{c as e,Q as t,j as r,m as o}from"./chunks/framework.DOi4mjdC.js";const p=JSON.parse('{"title":"关于新文艺","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),i={name:"about.md"};function l(n,a,h,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="关于新文艺" tabindex="-1">关于新文艺 <a class="header-anchor" href="#关于新文艺" aria-label="Permalink to &quot;关于新文艺&quot;">​</a></h1><h2 id="站点介绍" tabindex="-1">站点介绍 <a class="header-anchor" href="#站点介绍" aria-label="Permalink to &quot;站点介绍&quot;">​</a></h2><p>新文艺是一个专注于古典文学的垂直类内容展示与阅读平台。我们致力于免费开放古典文学优质内容，通过结构化分类、便捷检索功能，降低用户阅读和查找经典作品的门槛，助力传统文化普及。</p><h2 id="核心价值" tabindex="-1">核心价值 <a class="header-anchor" href="#核心价值" aria-label="Permalink to &quot;核心价值&quot;">​</a></h2><ul><li><strong>免费开放</strong>：所有内容完全免费，无需注册登录即可浏览全部内容</li><li><strong>内容全面</strong>：涵盖四大名著、经典诗词、明清小说、神魔志怪、公案侠义等多个品类</li><li><strong>阅读体验</strong>：简洁优雅的界面设计，专注阅读本身，支持响应式布局</li><li><strong>传统文化</strong>：助力传统文化普及，降低经典作品阅读门槛</li></ul><h2 id="内容分类" tabindex="-1">内容分类 <a class="header-anchor" href="#内容分类" aria-label="Permalink to &quot;内容分类&quot;">​</a></h2><p>本站古典文学作品按照以下分类进行组织：</p><h3 id="四大名著" tabindex="-1">四大名著 <a class="header-anchor" href="#四大名著" aria-label="Permalink to &quot;四大名著&quot;">​</a></h3><p>《红楼梦》《三国演义》《水浒传》《西游记》，中国古典文学巅峰之作。</p><h3 id="著名诗词" tabindex="-1">著名诗词 <a class="header-anchor" href="#著名诗词" aria-label="Permalink to &quot;著名诗词&quot;">​</a></h3><p>唐诗、宋词、元曲等经典诗词作品，按朝代和作者分类展示。</p><h3 id="明清小说" tabindex="-1">明清小说 <a class="header-anchor" href="#明清小说" aria-label="Permalink to &quot;明清小说&quot;">​</a></h3><p>晚清谴责小说、历史演义小说、白话短篇小说集等。</p><h3 id="神魔志怪" tabindex="-1">神魔志怪 <a class="header-anchor" href="#神魔志怪" aria-label="Permalink to &quot;神魔志怪&quot;">​</a></h3><p>《封神演义》《聊斋志异》等神魔志怪类作品。</p><h3 id="公案侠义" tabindex="-1">公案侠义 <a class="header-anchor" href="#公案侠义" aria-label="Permalink to &quot;公案侠义&quot;">​</a></h3><p>《包公案》《施公案》等公案侠义类小说。</p><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><p>本站采用纯前端静态架构，使用 VitePress 构建，无需后端服务与数据库，所有内容静态渲染。部署至静态托管平台，依托 CDN 加速，提升全球访问速度与稳定性。</p><h2 id="版权说明" tabindex="-1">版权说明 <a class="header-anchor" href="#版权说明" aria-label="Permalink to &quot;版权说明&quot;">​</a></h2><p>本站点仅展示<strong>公有领域古典文学作品</strong>，无版权侵权内容。所有内容均用于传统文化学习与传播，不用于商业盈利。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如有任何问题或建议，欢迎通过以下方式联系我们：</p><ul><li>邮箱：contact@xinwenyi.com</li><li>GitHub：<a href="https://github.com/xinwenyi" target="_blank" rel="noreferrer">https://github.com/xinwenyi</a></li></ul><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><p>感谢所有为传统文化传承做出贡献的先贤和 contemporaries。我们将继续努力，为传播和普及中国古典文学贡献一份力量。</p>',26)])])}const b=e(i,[["render",l]]);export{p as __pageData,b as default};
